CREATE TABLE IF NOT EXISTS competition (
    id BIGINT NOT NULL AUTO_INCREMENT,
    name VARCHAR(160) NOT NULL,
    track VARCHAR(32) NOT NULL,
    organizer VARCHAR(160) NOT NULL,
    season VARCHAR(160) NOT NULL DEFAULT '',
    level_class VARCHAR(20) NOT NULL,
    scope VARCHAR(20) NOT NULL,
    tags TEXT NOT NULL,
    description TEXT NOT NULL,
    official_url VARCHAR(500) NOT NULL DEFAULT '',
    status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',
    registration_deadline DATE NULL,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uk_competition_name (name),
    KEY idx_competition_status_track (status, track),
    KEY idx_competition_deadline (registration_deadline)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

